import React, { useEffect, useMemo, useState } from 'react';

const SEED_COMPANIES = [
  { id: 'niss-demo', name: 'NISS Realty Demo', short: 'NR', plan: 'Growth', status: 'Active', users: 8, color: '#635bff' },
  { id: 'northstar-demo', name: 'Northstar Properties', short: 'NP', plan: 'Starter', status: 'Active', users: 4, color: '#0f9f8f' },
];
const SEED_LEADS = [
  { id: 'LD-1048', name: 'Aarav Sharma', phone: '98765 43210', email: 'aarav@example.com', source: '99acres', budget: 12500000, location: 'Sector 150, Noida', type: '3 BHK', status: 'Hot', assigned: 'Rohit Verma', next: 'Today', notes: 'Looking for ready-to-move property' },
  { id: 'LD-1047', name: 'Priya Mehta', phone: '98111 22003', email: 'priya@example.com', source: 'Website', budget: 8500000, location: 'Greater Noida West', type: '2 BHK', status: 'Site Visit', assigned: 'Neha Singh', next: 'Tomorrow', notes: 'Family visit planned' },
  { id: 'LD-1046', name: 'Kabir Khanna', phone: '98990 11334', email: 'kabir@example.com', source: 'Referral', budget: 22000000, location: 'Sector 128, Noida', type: '4 BHK', status: 'Qualified', assigned: 'Rohit Verma', next: 'Oct 27', notes: 'Wants golf course view' },
  { id: 'LD-1045', name: 'Ananya Gupta', phone: '98100 55441', email: 'ananya@example.com', source: 'Facebook', budget: 6500000, location: 'Techzone 4', type: '2 BHK', status: 'New', assigned: 'Aman Yadav', next: 'Today', notes: 'First-time buyer' },
  { id: 'LD-1044', name: 'Vikram Sethi', phone: '98710 66771', email: 'vikram@example.com', source: 'Walk-in', budget: 18000000, location: 'Sector 75, Noida', type: '3 BHK', status: 'Negotiation', assigned: 'Neha Singh', next: 'Oct 28', notes: 'Discussing payment schedule' },
];
const SEED_EMPLOYEES = [
  { id: 'EMP-001', name: 'Rohit Verma', email: 'rohit@demo.in', role: 'Sales Manager', phone: '9876543210', salary: 35000, status: 'Active' },
  { id: 'EMP-002', name: 'Neha Singh', email: 'neha@demo.in', role: 'Property Consultant', phone: '9876543211', salary: 28000, status: 'Active' },
  { id: 'EMP-003', name: 'Aman Yadav', email: 'aman@demo.in', role: 'Sales Executive', phone: '9876543212', salary: 22000, status: 'Active' },
];
const NAV = [
  { group: 'WORKSPACE', items: [['Dashboard','▦'],['Leads','♧'],['Follow-ups','◷'],['Customers','♙'],['Properties','⌂'],['Projects','▤'],['Site Visits','⌖'],['Bookings','✓'],['Payments','₹']] },
  { group: 'PEOPLE', items: [['Employees','♧'],['Attendance','◷'],['Payroll','₹']] },
  { group: 'INSIGHTS', items: [['Reports','▥'],['Settings','⚙']] },
];
const money = (n) => new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', maximumFractionDigits: 0 }).format(Number(n || 0));
const read = (key, fallback) => { try { const v = localStorage.getItem(key); return v ? JSON.parse(v) : fallback; } catch { return fallback; } };
function uid(prefix='ID') { return `${prefix}-${Math.random().toString(36).slice(2,6).toUpperCase()}${Date.now().toString().slice(-4)}`; }

export default function App() {
  const [session, setSession] = useState(() => read('estateflow_session', null));
  const [companies, setCompanies] = useState(() => read('estateflow_companies', SEED_COMPANIES));
  const [page, setPage] = useState('Dashboard');
  const [mobileNav, setMobileNav] = useState(false);
  const [collapsed, setCollapsed] = useState(false);
  const [search, setSearch] = useState('');
  const [toast, setToast] = useState('');
  const [leads, setLeads] = useState(() => read('estateflow_leads_niss-demo', SEED_LEADS));
  const [employees, setEmployees] = useState(() => read('estateflow_employees_niss-demo', SEED_EMPLOYEES));
  const [attendance, setAttendance] = useState(() => read('estateflow_attendance_niss-demo', []));
  const [payroll, setPayroll] = useState(() => read('estateflow_payroll_niss-demo', []));
  const [properties, setProperties] = useState(() => read('estateflow_properties_niss-demo', [
    { id:'PR-201', name:'ATS Picturesque Reprieves', location:'Sector 152, Noida', type:'Apartment', price:12500000, status:'Available' },
    { id:'PR-202', name:'Ace Parkway', location:'Sector 150, Noida', type:'Apartment', price:9800000, status:'Available' },
    { id:'PR-203', name:'Commercial Plot 18', location:'Knowledge Park V', type:'Commercial', price:22000000, status:'On Hold' },
  ]));
  const [companyForm, setCompanyForm] = useState({ name:'', plan:'Starter', users:5, color:'#635bff' });
  const [leadFormOpen, setLeadFormOpen] = useState(false);
  const [leadForm, setLeadForm] = useState({ name:'', phone:'', email:'', source:'Website', budget:'', location:'', type:'2 BHK', status:'New', assigned:'', next:'Today', notes:'' });
  const [employeeFormOpen, setEmployeeFormOpen] = useState(false);
  const [employeeForm, setEmployeeForm] = useState({ name:'', email:'', role:'Sales Executive', phone:'', salary:'', status:'Active' });
  const [propertyFormOpen, setPropertyFormOpen] = useState(false);
  const [propertyForm, setPropertyForm] = useState({ name:'', location:'', type:'Apartment', price:'', status:'Available' });
  const [settings, setSettings] = useState(() => read('estateflow_settings_niss-demo', { companyName:'NISS Realty Demo', brandColor:'#635bff', currency:'INR', timezone:'Asia/Kolkata' }));

  useEffect(() => localStorage.setItem('estateflow_companies', JSON.stringify(companies)), [companies]);
  useEffect(() => localStorage.setItem('estateflow_session', JSON.stringify(session)), [session]);
  useEffect(() => { if (session?.companyId) {
    localStorage.setItem(`estateflow_leads_${session.companyId}`, JSON.stringify(leads));
    localStorage.setItem(`estateflow_employees_${session.companyId}`, JSON.stringify(employees));
    localStorage.setItem(`estateflow_attendance_${session.companyId}`, JSON.stringify(attendance));
    localStorage.setItem(`estateflow_payroll_${session.companyId}`, JSON.stringify(payroll));
    localStorage.setItem(`estateflow_properties_${session.companyId}`, JSON.stringify(properties));
    localStorage.setItem(`estateflow_settings_${session.companyId}`, JSON.stringify(settings));
  } }, [session, leads, employees, attendance, payroll, properties, settings]);
  useEffect(() => { if (toast) { const t = setTimeout(() => setToast(''), 2800); return () => clearTimeout(t); } }, [toast]);

  const company = companies.find(c => c.id === session?.companyId) || companies[0];
  const isSuper = session?.role === 'superadmin';
  const todayKey = new Date().toLocaleDateString('en-CA');
  const todayAttendance = attendance.filter(a => a.date === todayKey);
  const openLeads = leads.filter(l => !['Won','Lost'].includes(l.status));
  const overdue = leads.filter(l => ['Today','Overdue'].includes(l.next) && !['Won','Lost'].includes(l.status));
  const filteredLeads = useMemo(() => leads.filter(l => `${l.name} ${l.phone} ${l.location} ${l.id} ${l.assigned}`.toLowerCase().includes(search.toLowerCase())), [leads, search]);

  function login(role) {
    const next = role === 'superadmin'
      ? { role:'superadmin', name:'Platform Admin', email:'admin@estateflow.demo', companyId:null }
      : { role, name: role === 'owner' ? 'Workspace Owner' : 'Rohit Verma', email: role === 'owner' ? 'owner@crm-demo.in' : 'rohit@demo.in', companyId:'niss-demo' };
    setSession(next); setPage(role === 'superadmin' ? 'Companies' : 'Dashboard'); setToast('Welcome to EstateFlow CRM');
  }
  function logout() { setSession(null); setPage('Dashboard'); }
  function addLead(e) { e.preventDefault(); const lead = { ...leadForm, id:uid('LD'), budget:Number(leadForm.budget || 0), assigned:leadForm.assigned || employees[0]?.name || 'Unassigned' }; setLeads(prev => [lead, ...prev]); setLeadForm({ name:'', phone:'', email:'', source:'Website', budget:'', location:'', type:'2 BHK', status:'New', assigned:'', next:'Today', notes:'' }); setLeadFormOpen(false); setToast('Lead created successfully'); }
  function updateLead(id, changes) { setLeads(prev => prev.map(l => l.id === id ? { ...l, ...changes } : l)); setToast('Lead updated'); }
  function addEmployee(e) { e.preventDefault(); setEmployees(prev => [...prev, { ...employeeForm, id:uid('EMP'), salary:Number(employeeForm.salary || 0) }]); setEmployeeForm({ name:'', email:'', role:'Sales Executive', phone:'', salary:'', status:'Active' }); setEmployeeFormOpen(false); setToast('Employee added'); }
  function addProperty(e) { e.preventDefault(); setProperties(prev => [...prev, { ...propertyForm, id:uid('PR'), price:Number(propertyForm.price || 0) }]); setPropertyForm({ name:'', location:'', type:'Apartment', price:'', status:'Available' }); setPropertyFormOpen(false); setToast('Property added'); }
  function checkIn() { if (attendance.some(a => a.date === todayKey && a.employeeId === (session.role === 'employee' ? 'EMP-001' : 'OWNER'))) { setToast('Aaj ka check-in already recorded hai'); return; } setAttendance(prev => [{ id:uid('ATT'), employeeId:session.role === 'employee' ? 'EMP-001' : 'OWNER', name:session.name, date:todayKey, checkIn:new Date().toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'}), checkOut:'', status:'Present' }, ...prev]); setToast('Check-in recorded'); }
  function checkOut() { const key = session.role === 'employee' ? 'EMP-001' : 'OWNER'; const record = attendance.find(a => a.date === todayKey && a.employeeId === key && !a.checkOut); if (!record) { setToast('Pehle check-in karein'); return; } setAttendance(prev => prev.map(a => a.id === record.id ? { ...a, checkOut:new Date().toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'}) } : a)); setToast('Check-out recorded'); }
  function createPayroll() { const month = new Date().toLocaleDateString('en-IN',{month:'long',year:'numeric'}); const next = employees.map(e => ({ id:uid('PAY'), employeeId:e.id, employee:e.name, month, base:Number(e.salary||0), incentive:0, deductions:0, status:'Draft' })); setPayroll(prev => [...next, ...prev]); setToast('Payroll drafts created for active employees'); }
  function addCompany(e) { e.preventDefault(); const name = companyForm.name.trim(); if (!name) return; const id = `${name.toLowerCase().replace(/[^a-z0-9]+/g,'-')}-${Date.now().toString().slice(-4)}`; const c = { ...companyForm, id, short:name.split(/\s+/).slice(0,2).map(w=>w[0]).join('').toUpperCase(), status:'Active', users:Number(companyForm.users) }; setCompanies(prev => [...prev, c]); setCompanyForm({ name:'', plan:'Starter', users:5, color:'#635bff' }); setToast('Company workspace created'); }

  if (!session) return <Login onLogin={login} />;

  return <div className={`shell ${collapsed?'collapsed':''} ${mobileNav?'nav-open':''}`} style={{'--brand':company?.color || '#635bff'}}>
    {mobileNav && <button className="scrim" aria-label="Close navigation" onClick={() => setMobileNav(false)} />}
    <aside className="sidebar">
      <div className="brand"><div className="brand-logo">E<span>+</span></div><div className="brand-text"><strong>estateflow<span>.</span></strong><small>CRM PLATFORM</small></div><button className="collapse-btn" onClick={() => setCollapsed(v=>!v)} title="Collapse sidebar">‹</button></div>
      {isSuper ? <><div className="side-caption">PLATFORM</div><button className={`nav-item ${page==='Companies'?'active':''}`} onClick={()=>{setPage('Companies');setMobileNav(false)}}><span className="nav-icon">▦</span><span>Companies</span></button><button className={`nav-item ${page==='Platform Overview'?'active':''}`} onClick={()=>{setPage('Platform Overview');setMobileNav(false)}}><span className="nav-icon">◈</span><span>Platform overview</span></button><button className={`nav-item ${page==='Subscriptions'?'active':''}`} onClick={()=>{setPage('Subscriptions');setMobileNav(false)}}><span className="nav-icon">₹</span><span>Subscriptions</span></button></> : <>
        <div className="company-switch"><div className="company-avatar">{company?.short || 'EF'}</div><div className="company-meta"><b>{settings.companyName || company?.name}</b><small>{company?.plan || 'Growth'} plan</small></div><span>⌄</span></div>
        {NAV.map(group => <div key={group.group}><div className="side-caption">{group.group}</div>{group.items.filter(([label]) => session.role === 'owner' || !['Payments','Employees','Payroll','Reports','Settings'].includes(label)).map(([label, icon]) => <button key={label} className={`nav-item ${page===label?'active':''}`} onClick={() => {setPage(label);setMobileNav(false)}}><span className="nav-icon">{icon}</span><span>{label}</span>{label==='Leads' && <em>{openLeads.length}</em>}</button>)}</div>)}
      </>}
      <div className="sidebar-bottom"><div className="upgrade-card"><div className="upgrade-icon">✦</div><b>{isSuper?'Platform controls':'Make work flow.'}</b><p>{isSuper?'Manage client workspaces in one place.':'Your team workspace is ready to grow.'}</p><button onClick={()=>{setPage(isSuper?'Subscriptions':'Settings');setMobileNav(false)}}>{isSuper?'View plans':'Workspace settings'} <span>↗</span></button></div><div className="sidebar-user"><div className="avatar">{session.name.split(' ').map(x=>x[0]).slice(0,2).join('')}</div><div className="user-meta"><b>{session.name}</b><small>{session.role==='superadmin'?'Super Admin':session.role==='owner'?'Workspace Owner':'Sales Employee'}</small></div><button className="more-btn" onClick={logout} title="Sign out">↗</button></div></div>
    </aside>
    <main className="main">
      <header className="topbar"><button className="mobile-menu" onClick={()=>setMobileNav(v=>!v)}>☰</button><div className="breadcrumbs"><span>Workspace</span><b>/</b><strong>{page}</strong></div><div className="top-actions"><label className="search-box"><span>⌕</span><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search anything..."/><kbd>⌘ K</kbd></label><button className="icon-button" title="Notifications" onClick={()=>setToast('You are all caught up')}>♧<i/></button><div className="top-avatar">{session.name.split(' ').map(x=>x[0]).slice(0,2).join('')}</div></div></header>
      <div className="content">
        {isSuper ? <SuperAdminPage page={page} companies={companies} setPage={setPage} companyForm={companyForm} setCompanyForm={setCompanyForm} addCompany={addCompany} onOpenCompany={(c)=>{setSession({role:'owner',name:'Workspace Owner',email:'owner@crm-demo.in',companyId:c.id});setLeads(read(`estateflow_leads_${c.id}`,c.id==='niss-demo'?SEED_LEADS:[]));setEmployees(read(`estateflow_employees_${c.id}`,c.id==='niss-demo'?SEED_EMPLOYEES:[]));setAttendance(read(`estateflow_attendance_${c.id}`,[]));setPayroll(read(`estateflow_payroll_${c.id}`,[]));setProperties(read(`estateflow_properties_${c.id}`,[]));setSettings(read(`estateflow_settings_${c.id}`,{companyName:c.name,brandColor:c.color,currency:'INR',timezone:'Asia/Kolkata'}));setPage('Dashboard');setToast(`Opened ${c.name} demo workspace`)}}/> : <>
          {page==='Dashboard' && <Dashboard company={company} leads={leads} employees={employees} attendance={todayAttendance} overdue={overdue} properties={properties} setPage={setPage} money={money} />}
          {page==='Leads' && <LeadsPage leads={filteredLeads} allLeads={leads} employees={employees} onAdd={()=>setLeadFormOpen(true)} onUpdate={updateLead} search={search} money={money} />}
          {page==='Follow-ups' && <FollowUpsPage leads={leads} updateLead={updateLead} />}
          {page==='Customers' && <CustomersPage leads={leads} />}
          {page==='Properties' && <PropertiesPage properties={properties} onAdd={()=>setPropertyFormOpen(true)} />}
          {page==='Projects' && <ProjectsPage properties={properties} />}
          {page==='Site Visits' && <SiteVisitsPage leads={leads} />}
          {page==='Bookings' && <BookingsPage leads={leads} />}
          {page==='Payments' && <PaymentsPage payroll={payroll} money={money} />}
          {page==='Employees' && <EmployeesPage employees={employees} onAdd={()=>setEmployeeFormOpen(true)} />}
          {page==='Attendance' && <AttendancePage attendance={attendance} employees={employees} checkIn={checkIn} checkOut={checkOut} todayKey={todayKey} role={session.role} />}
          {page==='Payroll' && <PayrollPage payroll={payroll} employees={employees} createPayroll={createPayroll} setPayroll={setPayroll} money={money} />}
          {page==='Reports' && <ReportsPage leads={leads} employees={employees} properties={properties} money={money} />}
          {page==='Settings' && <SettingsPage settings={settings} setSettings={setSettings} company={company} setToast={setToast} />}
        </>}
      </div>
      <footer className="footer"><span>EstateFlow CRM <b>•</b> Workspace edition</span><span>Built for real estate teams · <button onClick={()=>setToast('Prototype version — connect production backend before real data.')}>System status: Demo</button></span></footer>
    </main>
    {leadFormOpen && <Modal title="Create new lead" onClose={()=>setLeadFormOpen(false)}><form className="form-grid" onSubmit={addLead}><Field label="Customer name" required><input required value={leadForm.name} onChange={e=>setLeadForm({...leadForm,name:e.target.value})} placeholder="e.g. Rahul Sharma"/></Field><Field label="Phone number" required><input required value={leadForm.phone} onChange={e=>setLeadForm({...leadForm,phone:e.target.value})} placeholder="Mobile number"/></Field><Field label="Email"><input type="email" value={leadForm.email} onChange={e=>setLeadForm({...leadForm,email:e.target.value})} placeholder="name@email.com"/></Field><Field label="Lead source"><select value={leadForm.source} onChange={e=>setLeadForm({...leadForm,source:e.target.value})}>{['Website','99acres','MagicBricks','Referral','Facebook','Instagram','Walk-in','WhatsApp','Other'].map(x=><option>{x}</option>)}</select></Field><Field label="Budget (₹)"><input type="number" value={leadForm.budget} onChange={e=>setLeadForm({...leadForm,budget:e.target.value})} placeholder="10000000"/></Field><Field label="Preferred location"><input value={leadForm.location} onChange={e=>setLeadForm({...leadForm,location:e.target.value})} placeholder="Sector / city"/></Field><Field label="Property preference"><select value={leadForm.type} onChange={e=>setLeadForm({...leadForm,type:e.target.value})}>{['1 BHK','2 BHK','3 BHK','4 BHK','Villa','Plot','Commercial','Office'].map(x=><option>{x}</option>)}</select></Field><Field label="Lead status"><select value={leadForm.status} onChange={e=>setLeadForm({...leadForm,status:e.target.value})}>{['New','Qualified','Hot','Site Visit','Negotiation','Won','Lost'].map(x=><option>{x}</option>)}</select></Field><Field label="Assign to"><select value={leadForm.assigned} onChange={e=>setLeadForm({...leadForm,assigned:e.target.value})}><option value="">Auto / Unassigned</option>{employees.map(x=><option>{x.name}</option>)}</select></Field><Field label="Next follow-up"><select value={leadForm.next} onChange={e=>setLeadForm({...leadForm,next:e.target.value})}>{['Today','Tomorrow','Oct 27','Oct 28','Next week','Not scheduled'].map(x=><option>{x}</option>)}</select></Field><Field label="Notes" wide><textarea value={leadForm.notes} onChange={e=>setLeadForm({...leadForm,notes:e.target.value})} placeholder="Customer requirements..."/></Field><div className="modal-actions"><button type="button" className="btn secondary" onClick={()=>setLeadFormOpen(false)}>Cancel</button><button className="btn primary">Create lead</button></div></form></Modal>}
    {employeeFormOpen && <Modal title="Add team member" onClose={()=>setEmployeeFormOpen(false)}><form className="form-grid" onSubmit={addEmployee}><Field label="Full name" required><input required value={employeeForm.name} onChange={e=>setEmployeeForm({...employeeForm,name:e.target.value})}/></Field><Field label="Work email" required><input required type="email" value={employeeForm.email} onChange={e=>setEmployeeForm({...employeeForm,email:e.target.value})}/></Field><Field label="Role"><select value={employeeForm.role} onChange={e=>setEmployeeForm({...employeeForm,role:e.target.value})}>{['Sales Executive','Sales Manager','Property Consultant','HR','Accountant','Operations'].map(x=><option>{x}</option>)}</select></Field><Field label="Phone"><input value={employeeForm.phone} onChange={e=>setEmployeeForm({...employeeForm,phone:e.target.value})}/></Field><Field label="Monthly base salary (₹)"><input type="number" value={employeeForm.salary} onChange={e=>setEmployeeForm({...employeeForm,salary:e.target.value})}/></Field><div className="modal-actions"><button type="button" className="btn secondary" onClick={()=>setEmployeeFormOpen(false)}>Cancel</button><button className="btn primary">Add employee</button></div></form></Modal>}
    {propertyFormOpen && <Modal title="Add property inventory" onClose={()=>setPropertyFormOpen(false)}><form className="form-grid" onSubmit={addProperty}><Field label="Property / project name" required><input required value={propertyForm.name} onChange={e=>setPropertyForm({...propertyForm,name:e.target.value})}/></Field><Field label="Location" required><input required value={propertyForm.location} onChange={e=>setPropertyForm({...propertyForm,location:e.target.value})}/></Field><Field label="Type"><select value={propertyForm.type} onChange={e=>setPropertyForm({...propertyForm,type:e.target.value})}>{['Apartment','Villa','Plot','Commercial','Office','Retail'].map(x=><option>{x}</option>)}</select></Field><Field label="Price (₹)"><input type="number" value={propertyForm.price} onChange={e=>setPropertyForm({...propertyForm,price:e.target.value})}/></Field><Field label="Availability"><select value={propertyForm.status} onChange={e=>setPropertyForm({...propertyForm,status:e.target.value})}>{['Available','On Hold','Sold','Unavailable'].map(x=><option>{x}</option>)}</select></Field><div className="modal-actions"><button type="button" className="btn secondary" onClick={()=>setPropertyFormOpen(false)}>Cancel</button><button className="btn primary">Add property</button></div></form></Modal>}
    {toast && <div className="toast"><span>✓</span>{toast}</div>}
  </div>;
}

function Login({onLogin}) { const [role,setRole]=useState('owner'); return <div className="login-page"><div className="login-left"><div className="brand login-brand"><div className="brand-logo">E<span>+</span></div><div className="brand-text"><strong>estateflow<span>.</span></strong><small>CRM PLATFORM</small></div></div><div className="login-hero"><span className="pill light">REAL ESTATE, IN ONE FLOW</span><h1>Every lead has a story.<br/><em>Close the next chapter.</em></h1><p>The modern workspace for property teams — from first enquiry to final booking.</p><div className="hero-points"><span>✓ Smart lead pipeline</span><span>✓ Team performance</span><span>✓ Sales, visits & payroll</span></div></div><div className="login-decoration"><div className="orbit orbit-one"/><div className="orbit orbit-two"/><div className="float-card card-one"><span className="mini-icon purple">↗</span><div><small>Conversion rate</small><b>+24.8%</b></div></div><div className="float-card card-two"><span className="mini-icon green">✓</span><div><small>Site visits today</small><b>12 scheduled</b></div></div></div><div className="login-foot">A flexible CRM workspace for growing real estate teams.</div></div><div className="login-right"><form className="login-box" onSubmit={e=>{e.preventDefault();onLogin(role)}}><span className="eyebrow">WELCOME TO ESTATEFLOW</span><h2>Sign in to your workspace</h2><p>Choose a demo role to explore the product.</p><div className="role-cards"><button type="button" className={role==='owner'?'chosen':''} onClick={()=>setRole('owner')}><span>♙</span><b>Company Owner</b><small>Manage your team</small></button><button type="button" className={role==='employee'?'chosen':''} onClick={()=>setRole('employee')}><span>♧</span><b>Employee</b><small>Your daily workspace</small></button><button type="button" className={role==='superadmin'?'chosen':''} onClick={()=>setRole('superadmin')}><span>✦</span><b>Super Admin</b><small>Manage client companies</small></button></div><label className="login-input-label">Demo email<input readOnly value={role==='superadmin'?'admin@estateflow.demo':role==='owner'?'owner@crm-demo.in':'rohit@demo.in'}/></label><label className="login-input-label">Demo password<input readOnly value={role==='superadmin'?'Admin@123':role==='owner'?'Owner@123':'Employee@123'}/></label><button className="btn primary login-btn">Continue to CRM <span>→</span></button><div className="login-warning"><span>ⓘ</span><p><b>Demo environment</b><br/>Demo role switching is for preview only. Production authentication and server-side access controls are not connected yet.</p></div></form></div></div>; }

function Dashboard({company,leads,employees,attendance,overdue,properties,setPage,money}) { const won=leads.filter(l=>l.status==='Won').length; const hot=leads.filter(l=>['Hot','Negotiation'].includes(l.status)).length; const conversion=leads.length?Math.round(won/leads.length*100):0; return <><div className="page-heading"><div><div className="eyebrow">MONDAY, OCTOBER 26, 2026 <span className="live-dot"/></div><h1>Good morning, <span>Team.</span> <span className="wave">✦</span></h1><p>Here's what's happening with your business today.</p></div><div className="heading-actions"><button className="btn secondary" onClick={()=>setPage('Reports')}>↗ View reports</button><button className="btn primary" onClick={()=>setPage('Leads')}>＋ New lead</button></div></div><div className="hero-banner"><div className="hero-banner-copy"><span className="banner-tag">✦ YOUR BUSINESS AT A GLANCE</span><h2>Make every opportunity<br/>count.</h2><p>Stay ahead of follow-ups, empower your team, and turn more enquiries into successful deals.</p><button onClick={()=>setPage('Leads')}>Explore your pipeline <span>→</span></button></div><div className="hero-visual"><div className="visual-ring ring-a"/><div className="visual-ring ring-b"/><div className="visual-center">E<span>+</span></div><div className="visual-stat stat-a"><small>Open leads</small><b>{leads.filter(l=>!['Won','Lost'].includes(l.status)).length}</b><span>↗ Active pipeline</span></div><div className="visual-stat stat-b"><small>Properties</small><b>{properties.length}</b><span>▧ In inventory</span></div></div><div className="banner-orb orb-a"/><div className="banner-orb orb-b"/></div><div className="stats-grid"><Stat label="Total leads" value={leads.length} change="Live pipeline" icon="♧" tone="purple" foot={`${hot} hot / negotiation`} /><Stat label="Follow-ups due" value={overdue.length} change="Needs attention" icon="◷" tone="orange" foot="Prioritise today's calls"/><Stat label="Team members" value={employees.length} change="Active roster" icon="♙" tone="blue" foot={`${attendance.length} attendance records today`}/><Stat label="Lead conversion" value={`${conversion}%`} change="Won / total leads" icon="↗" tone="green" foot={`${won} won deals recorded`}/></div><div className="dashboard-grid"><section className="panel pipeline-panel"><div className="panel-head"><div><h3>Lead pipeline</h3><p>Track opportunities across every stage</p></div><button className="text-action" onClick={()=>setPage('Leads')}>View all →</button></div><div className="pipeline-bars">{[['New',leads.filter(l=>l.status==='New').length,'#8b83ff'],['Qualified',leads.filter(l=>l.status==='Qualified').length,'#5f8cf7'],['Hot',leads.filter(l=>l.status==='Hot').length,'#e7a14b'],['Site Visit',leads.filter(l=>l.status==='Site Visit').length,'#26b7a4'],['Negotiation',leads.filter(l=>l.status==='Negotiation').length,'#d57ac5'],['Won',won,'#39b985']].map(([label,count,color])=><div className="pipeline-row" key={label}><span>{label}</span><div className="bar-track"><div className="bar-fill" style={{width:`${Math.max(4,count/Math.max(leads.length,1)*100)}%`,background:color}}/></div><b>{count}</b></div>)}</div><div className="panel-bottom-note"><span className="note-icon">✦</span><span><b>{hot} high-intent leads</b> are in Hot or Negotiation. Keep momentum with a timely follow-up.</span></div></section><section className="panel tasks-panel"><div className="panel-head"><div><h3>Priority follow-ups</h3><p>Leads that need your attention</p></div><button className="text-action" onClick={()=>setPage('Follow-ups')}>See schedule →</button></div><div className="task-list">{overdue.slice(0,4).map((l,i)=><div className="task-row" key={l.id}><div className={`task-avatar av-${i%4}`}>{l.name.split(' ').map(n=>n[0]).join('').slice(0,2)}</div><div className="task-info"><b>{l.name}</b><small>{l.location||'Location not added'} · {l.assigned}</small></div><span className={`status-pill ${l.next==='Today'?'warning':'neutral'}`}>{l.next}</span></div>)}{!overdue.length&&<Empty title="You're all caught up" desc="No priority follow-ups at the moment."/>}</div><button className="full-action" onClick={()=>setPage('Follow-ups')}>Open follow-up manager <span>→</span></button></section></div><div className="dashboard-grid lower-grid"><section className="panel activity-panel"><div className="panel-head"><div><h3>Recent opportunities</h3><p>Latest lead activity in your workspace</p></div><button className="text-action" onClick={()=>setPage('Leads')}>All leads →</button></div><div className="table-wrap"><table><thead><tr><th>CONTACT</th><th>INTEREST</th><th>OWNER</th><th>STATUS</th><th>BUDGET</th></tr></thead><tbody>{leads.slice(0,5).map((l,i)=><tr key={l.id}><td><div className="contact-cell"><div className={`tiny-avatar av-${i%4}`}>{l.name.split(' ').map(n=>n[0]).join('').slice(0,2)}</div><div><b>{l.name}</b><small>{l.id}</small></div></div></td><td>{l.type||'—'}<small className="cell-sub">{l.location}</small></td><td>{l.assigned||'Unassigned'}</td><td><Status value={l.status}/></td><td>{money(l.budget)}</td></tr>)}</tbody></table></div></section><section className="panel team-panel"><div className="panel-head"><div><h3>Team snapshot</h3><p>Who's on your roster</p></div><button className="text-action" onClick={()=>setPage('Employees')}>Manage →</button></div>{employees.slice(0,4).map((e,i)=><div className="team-row" key={e.id}><div className={`team-avatar av-${i%4}`}>{e.name.split(' ').map(n=>n[0]).join('').slice(0,2)}</div><div className="team-person"><b>{e.name}</b><small>{e.role}</small></div><span className={`online-state ${e.status==='Active'?'online':'offline'}`}>{e.status}</span></div>)}<div className="team-footer"><div className="mini-stack">{employees.slice(0,4).map((e,i)=><span className={`team-avatar av-${i%4}`} key={e.id}>{e.name[0]}</span>)}</div><span>{employees.length} team members in this workspace</span></div></section></div></>; }
function Stat({label,value,change,icon,tone,foot}) { return <div className="stat-card"><div className="stat-top"><span>{label}</span><span className={`stat-icon ${tone}`}>{icon}</span></div><div className="stat-value">{value}</div><div className="stat-change"><span className="change-chip">↗</span>{change}</div><div className="stat-foot">{foot}</div></div>; }
function SuperAdminPage({page,companies,setPage,companyForm,setCompanyForm,addCompany,onOpenCompany}) { const [showForm,setShowForm]=useState(false); const active=companies.filter(c=>c.status==='Active').length; return <><div className="page-heading"><div><div className="eyebrow">PLATFORM CONTROL CENTER</div><h1>{page==='Companies'?'Client workspaces':page==='Subscriptions'?'Plans & subscriptions':'Platform overview'}</h1><p>Manage customer companies from one central workspace.</p></div><div className="heading-actions"><button className="btn primary" onClick={()=>{setPage('Companies');setShowForm(true)}}>＋ Add company</button></div></div><div className="stats-grid"><Stat label="Total workspaces" value={companies.length} change="All registered companies" icon="▦" tone="purple" foot="Across all plans"/><Stat label="Active workspaces" value={active} change="Ready to use" icon="✓" tone="green" foot="Workspace status"/><Stat label="Total seats" value={companies.reduce((s,c)=>s+Number(c.users||0),0)} change="Configured user capacity" icon="♙" tone="blue" foot="Seat limits are demo only"/><Stat label="Plans configured" value={new Set(companies.map(c=>c.plan)).size} change="Starter & Growth" icon="◇" tone="orange" foot="Billing not connected"/></div>{page==='Subscriptions'&&<div className="plan-grid">{[['Starter','₹299','1–2 seats','Leads, tasks, basic reports'],['Growth','₹799','Up to 5 seats','Attendance, visits, team reports'],['Business','₹1,499','Up to 15 seats','Advanced insights, permissions']].map(p=><div className="panel plan-card" key={p[0]}><span className="pill">DEMO PLAN</span><h2>{p[0]}</h2><h3>{p[1]}<small>/ month</small></h3><p>{p[2]}</p><div className="plan-rule"/><p>{p[3]}</p><button className="btn secondary" onClick={()=>setPage('Companies')}>Assign from workspace</button></div>)}</div>}{page!=='Subscriptions'&&<section className="panel companies-panel"><div className="panel-head"><div><h3>All client workspaces</h3><p>Each workspace represents a separate company tenant in the future production backend.</p></div><div className="table-count">{companies.length} workspaces</div></div><div className="table-wrap"><table><thead><tr><th>COMPANY</th><th>PLAN</th><th>SEATS</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody>{companies.map(c=><tr key={c.id}><td><div className="company-table-cell"><div className="company-avatar" style={{background:c.color}}>{c.short}</div><div><b>{c.name}</b><small>{c.id}</small></div></div></td><td><span className="plan-label">{c.plan}</span></td><td>{c.users} seats</td><td><Status value={c.status}/></td><td><button className="btn small secondary" onClick={()=>onOpenCompany(c)}>Open demo ↗</button></td></tr>)}</tbody></table></div></section>}{showForm&&<Modal title="Create client workspace" onClose={()=>setShowForm(false)}><form className="form-grid" onSubmit={e=>{addCompany(e);setShowForm(false)}}><Field label="Company / brand name" required><input required value={companyForm.name} onChange={e=>setCompanyForm({...companyForm,name:e.target.value})} placeholder="e.g. BlueSky Realty"/></Field><Field label="Plan"><select value={companyForm.plan} onChange={e=>setCompanyForm({...companyForm,plan:e.target.value})}>{['Starter','Growth','Business','Enterprise'].map(x=><option>{x}</option>)}</select></Field><Field label="Seat limit"><input type="number" min="1" value={companyForm.users} onChange={e=>setCompanyForm({...companyForm,users:e.target.value})}/></Field><Field label="Brand color"><input type="color" value={companyForm.color} onChange={e=>setCompanyForm({...companyForm,color:e.target.value})}/></Field><div className="notice wide">This creates a demo workspace record in this browser. Production company isolation, authentication, and billing must be enforced by the backend before selling access.</div><div className="modal-actions"><button type="button" className="btn secondary" onClick={()=>setShowForm(false)}>Cancel</button><button className="btn primary">Create workspace</button></div></form></Modal>}</>; }
function LeadsPage({leads,allLeads,employees,onAdd,onUpdate,search}) { const [view,setView]=useState('Table'); return <><div className="page-heading"><div><div className="eyebrow">SALES WORKSPACE</div><h1>Lead management</h1><p>Capture every enquiry, assign ownership, and keep the next action clear.</p></div><div className="heading-actions"><button className="btn secondary" onClick={()=>{const csv=['id,name,phone,email,source,budget,location,status,assigned,next',...leads.map(l=>[l.id,l.name,l.phone,l.email,l.source,l.budget,l.location,l.status,l.assigned,l.next].map(v=>`"${String(v||'').replace(/"/g,'""')}"`).join(','))].join('\n'); const blob=new Blob([csv],{type:'text/csv'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='estateflow-leads.csv';a.click();URL.revokeObjectURL(url)}}>↓ Export CSV</button><button className="btn primary" onClick={onAdd}>＋ Add lead</button></div></div><div className="stats-grid compact-stats"><Stat label="All leads" value={allLeads.length} change="In this workspace" icon="♧" tone="purple" foot="Total captured records"/><Stat label="New leads" value={allLeads.filter(l=>l.status==='New').length} change="Awaiting qualification" icon="✦" tone="blue" foot="Make first contact"/><Stat label="Hot opportunities" value={allLeads.filter(l=>['Hot','Negotiation'].includes(l.status)).length} change="High intent" icon="↗" tone="orange" foot="Prioritise follow-up"/><Stat label="Closed won" value={allLeads.filter(l=>l.status==='Won').length} change="Successful deals" icon="✓" tone="green" foot="Recorded conversions"/></div><section className="panel"><div className="panel-head"><div><h3>All enquiries</h3><p>{leads.length} results · Use status to move a lead through the pipeline</p></div><div className="view-toggle"><button className={view==='Table'?'selected':''} onClick={()=>setView('Table')}>☷ Table</button><button className={view==='Pipeline'?'selected':''} onClick={()=>setView('Pipeline')}>▦ Pipeline</button></div></div>{view==='Table'?<div className="table-wrap"><table><thead><tr><th>LEAD</th><th>PROPERTY NEED</th><th>ASSIGNED TO</th><th>STATUS</th><th>NEXT FOLLOW-UP</th><th>UPDATE</th></tr></thead><tbody>{leads.map((l,i)=><tr key={l.id}><td><div className="contact-cell"><div className={`tiny-avatar av-${i%4}`}>{l.name.split(' ').map(n=>n[0]).join('').slice(0,2)}</div><div><b>{l.name}</b><small>{l.id} · {l.phone}</small></div></div></td><td><b>{l.type}</b><small className="cell-sub">{l.location||'No location'}</small><small className="cell-sub">{money(l.budget)}</small></td><td><select className="inline-select" value={l.assigned||''} onChange={e=>onUpdate(l.id,{assigned:e.target.value})}><option value="">Unassigned</option>{employees.map(e=><option key={e.id}>{e.name}</option>)}</select></td><td><Status value={l.status}/></td><td>{l.next||'Not scheduled'}</td><td><select className="inline-select" value={l.status} onChange={e=>onUpdate(l.id,{status:e.target.value})}>{['New','Qualified','Hot','Site Visit','Negotiation','Won','Lost'].map(x=><option>{x}</option>)}</select></td></tr>)}</tbody></table>{!leads.length&&<Empty title="No leads found" desc={search?'Try a different search.':'Add your first lead to start building a pipeline.'}/>}</div>:<div className="kanban">{['New','Qualified','Hot','Site Visit','Negotiation','Won'].map(stage=><div className="kanban-col" key={stage}><div className="kanban-head"><span>{stage}</span><b>{leads.filter(l=>l.status===stage).length}</b></div>{leads.filter(l=>l.status===stage).map(l=><div className="kanban-card" key={l.id}><small>{l.id}</small><b>{l.name}</b><span>{l.location}</span><strong>{money(l.budget)}</strong><select value={l.status} onChange={e=>onUpdate(l.id,{status:e.target.value})}>{['New','Qualified','Hot','Site Visit','Negotiation','Won','Lost'].map(x=><option>{x}</option>)}</select></div>)}</div>)}</div>}</section></>; }
function FollowUpsPage({leads,updateLead}) { const [filter,setFilter]=useState('All'); const items=leads.filter(l=>!['Won','Lost'].includes(l.status)).filter(l=>filter==='All'||l.next===filter); return <><PageTitle eyebrow="STAY AHEAD" title="Follow-up manager" subtitle="The next best action is always visible."/><div className="filter-row">{['All','Today','Tomorrow','Overdue','Not scheduled'].map(x=><button className={`filter-chip ${filter===x?'selected':''}`} onClick={()=>setFilter(x)} key={x}>{x}</button>)}</div><div className="followup-grid">{items.map((l,i)=><div className="panel follow-card" key={l.id}><div className="follow-card-top"><div className={`tiny-avatar av-${i%4}`}>{l.name.split(' ').map(n=>n[0]).join('').slice(0,2)}</div><Status value={l.status}/></div><h3>{l.name}</h3><p>{l.location||'Location not added'} · {l.type}</p><div className="follow-meta"><span>◷ {l.next||'Not scheduled'}</span><span>♙ {l.assigned||'Unassigned'}</span></div><div className="follow-actions"><a href={`tel:${String(l.phone).replace(/\D/g,'')}`} className="btn secondary">☎ Call</a><button className="btn primary" onClick={()=>updateLead(l.id,{next:'Tomorrow'})}>Done · reschedule</button></div></div>)}{!items.length&&<Empty title="No follow-ups in this view" desc="Try another filter or update a lead's next action."/>}</div></>; }
function CustomersPage({leads}) { const customers=leads.filter(l=>['Won','Negotiation','Site Visit'].includes(l.status)); return <><PageTitle eyebrow="RELATIONSHIP HUB" title="Customers" subtitle="Customers and qualified opportunities in one place."/><div className="panel"><div className="panel-head"><div><h3>Customer directory</h3><p>Derived from active and converted leads in this demo.</p></div><span className="table-count">{customers.length} contacts</span></div><div className="table-wrap"><table><thead><tr><th>CUSTOMER</th><th>CONTACT</th><th>PROPERTY INTEREST</th><th>OWNER</th><th>STAGE</th></tr></thead><tbody>{customers.map((l,i)=><tr key={l.id}><td><div className="contact-cell"><div className={`tiny-avatar av-${i%4}`}>{l.name[0]}</div><b>{l.name}</b></div></td><td>{l.phone}<small className="cell-sub">{l.email}</small></td><td>{l.type}<small className="cell-sub">{l.location}</small></td><td>{l.assigned}</td><td><Status value={l.status}/></td></tr>)}</tbody></table></div></div></>; }
function PropertiesPage({properties,onAdd}) { return <><PageTitle eyebrow="INVENTORY" title="Property inventory" subtitle="Keep listings, availability and pricing in sync with your team." actions={<button className="btn primary" onClick={onAdd}>＋ Add property</button>}/><div className="property-grid">{properties.map((p,i)=><div className="panel property-card" key={p.id}><div className={`property-art art-${i%3}`}><span className="property-type">{p.type}</span><span className="property-status">{p.status}</span><div className="building-illustration"><i/><i/><i/><i/><i/><i/><i/><i/><i/></div></div><div className="property-content"><small>{p.id}</small><h3>{p.name}</h3><p>⌖ {p.location}</p><div className="property-bottom"><b>{money(p.price)}</b><button className="text-action" onClick={()=>navigator.clipboard?.writeText(`${p.name} — ${p.location} — ${money(p.price)}`)}>Copy details ↗</button></div></div></div>)}</div>{!properties.length&&<Empty title="No inventory yet" desc="Add your first property to match with buyer requirements."/>}</>; }
function ProjectsPage({properties}) { const groups=[...new Set(properties.map(p=>p.location))]; return <><PageTitle eyebrow="DEVELOPMENT TRACKER" title="Projects" subtitle="A location-wise overview of the inventory your team is handling."/><div className="stats-grid"><Stat label="Projects / locations" value={groups.length} change="Distinct locations" icon="▤" tone="purple" foot="Based on current inventory"/><Stat label="Available inventory" value={properties.filter(p=>p.status==='Available').length} change="Can be offered" icon="⌂" tone="green" foot="Availability from demo data"/><Stat label="On hold" value={properties.filter(p=>p.status==='On Hold').length} change="Needs verification" icon="◷" tone="orange" foot="Confirm before pitching"/><Stat label="Total listings" value={properties.length} change="Across workspace" icon="▦" tone="blue" foot="All property records"/></div><div className="project-grid">{groups.map((g,i)=><div className="panel project-card" key={g}><div className={`project-icon pi-${i%3}`}>⌂</div><div><h3>{g}</h3><p>{properties.filter(p=>p.location===g).length} listing(s) in this area</p></div><div className="project-list">{properties.filter(p=>p.location===g).map(p=><div key={p.id}><span>{p.name}</span><b>{money(p.price)}</b></div>)}</div></div>)}</div></>; }
function SiteVisitsPage({leads}) { const visits=leads.filter(l=>l.status==='Site Visit'); return <><PageTitle eyebrow="FIELD SALES" title="Site visits" subtitle="Coordinate buyer visits and capture the next action after every tour."/><div className="stats-grid"><Stat label="Visits in pipeline" value={visits.length} change="Lead stage based" icon="⌖" tone="purple" foot="Schedule confirmations"/><Stat label="Need scheduling" value={visits.filter(l=>!l.next||l.next==='Not scheduled').length} change="Action required" icon="◷" tone="orange" foot="Confirm with customer"/><Stat label="Assigned agents" value={new Set(visits.map(l=>l.assigned)).size} change="Team coverage" icon="♙" tone="blue" foot="Across current visits"/><Stat label="Visit outcomes" value="—" change="Not yet captured" icon="✓" tone="green" foot="Add backend visit outcomes"/></div><div className="panel"><div className="panel-head"><div><h3>Visit schedule queue</h3><p>Current leads marked as Site Visit</p></div></div><div className="table-wrap"><table><thead><tr><th>BUYER</th><th>LOCATION / TYPE</th><th>AGENT</th><th>PLANNED DATE</th><th>FOLLOW-UP</th></tr></thead><tbody>{visits.map(l=><tr key={l.id}><td><b>{l.name}</b><small className="cell-sub">{l.phone}</small></td><td>{l.location}<small className="cell-sub">{l.type}</small></td><td>{l.assigned}</td><td>{l.next}</td><td>{l.notes||'Capture visit feedback'}</td></tr>)}</tbody></table></div></div></>; }
function BookingsPage({leads}) { const won=leads.filter(l=>l.status==='Won'); return <><PageTitle eyebrow="DEAL DESK" title="Bookings" subtitle="Review closed deals and keep upcoming bookings visible."/><div className="stats-grid"><Stat label="Closed won" value={won.length} change="Marked as Won" icon="✓" tone="green" foot="Based on lead status"/><Stat label="Pipeline value" value={money(leads.filter(l=>!['Won','Lost'].includes(l.status)).reduce((s,l)=>s+Number(l.budget||0),0))} change="Open opportunity budget" icon="₹" tone="purple" foot="Not a revenue forecast"/><Stat label="Booking documents" value="0" change="Not integrated" icon="▤" tone="blue" foot="Document workflow to build"/><Stat label="Pending payments" value="—" change="Connect payment records" icon="◷" tone="orange" foot="No real transactions in demo"/></div><div className="panel"><div className="panel-head"><div><h3>Won deals</h3><p>Leads moved to Won stage</p></div></div>{won.length?<div className="table-wrap"><table><thead><tr><th>CUSTOMER</th><th>LOCATION</th><th>ASSIGNED</th><th>BUDGET</th></tr></thead><tbody>{won.map(l=><tr key={l.id}><td>{l.name}</td><td>{l.location}</td><td>{l.assigned}</td><td>{money(l.budget)}</td></tr>)}</tbody></table></div>:<Empty title="No confirmed bookings yet" desc="When a lead is moved to Won, it will appear here. Booking documents and payments require a dedicated workflow."/>}</div></>; }
function PaymentsPage({payroll,money}) { const paid=payroll.filter(p=>p.status==='Paid').reduce((s,p)=>s+Number(p.base||0)+Number(p.incentive||0)-Number(p.deductions||0),0); return <><PageTitle eyebrow="FINANCE" title="Payments" subtitle="A high-level view of recorded payroll payouts in this prototype."/><div className="stats-grid"><Stat label="Recorded payouts" value={money(paid)} change="Payroll marked Paid" icon="₹" tone="green" foot="Demo records only"/><Stat label="Payroll entries" value={payroll.length} change="All generated entries" icon="▤" tone="purple" foot="Open Payroll to manage"/><Stat label="Pending drafts" value={payroll.filter(p=>p.status==='Draft').length} change="Not paid" icon="◷" tone="orange" foot="Requires owner review"/><Stat label="Customer collections" value="Not connected" change="No payment gateway" icon="↗" tone="blue" foot="Real collections not recorded"/></div><div className="notice">This is not a payment gateway or accounting ledger. Do not treat demo values as actual transactions or tax records.</div></>; }
function EmployeesPage({employees,onAdd}) { return <><PageTitle eyebrow="PEOPLE OPERATIONS" title="Team members" subtitle="Manage your people, roles and monthly base salary records." actions={<button className="btn primary" onClick={onAdd}>＋ Add employee</button>}/><div className="stats-grid"><Stat label="Team size" value={employees.length} change="Configured employee records" icon="♙" tone="purple" foot="Demo workspace roster"/><Stat label="Active members" value={employees.filter(e=>e.status==='Active').length} change="Available roster" icon="✓" tone="green" foot="Status from employee records"/><Stat label="Monthly base payroll" value={money(employees.reduce((s,e)=>s+Number(e.salary||0),0))} change="Before incentives/deductions" icon="₹" tone="blue" foot="Estimate only"/><Stat label="Roles" value={new Set(employees.map(e=>e.role)).size} change="Unique job roles" icon="▦" tone="orange" foot="Permission matrix not connected"/></div><div className="panel"><div className="panel-head"><div><h3>Employee directory</h3><p>Role and salary information is visible to owner in this prototype.</p></div></div><div className="table-wrap"><table><thead><tr><th>EMPLOYEE</th><th>ROLE</th><th>CONTACT</th><th>MONTHLY BASE</th><th>STATUS</th></tr></thead><tbody>{employees.map((e,i)=><tr key={e.id}><td><div className="contact-cell"><div className={`tiny-avatar av-${i%4}`}>{e.name.split(' ').map(n=>n[0]).join('').slice(0,2)}</div><div><b>{e.name}</b><small>{e.id}</small></div></div></td><td>{e.role}</td><td>{e.email}<small className="cell-sub">{e.phone}</small></td><td>{money(e.salary)}</td><td><Status value={e.status}/></td></tr>)}</tbody></table></div></div></>; }
function AttendancePage({attendance,employees,checkIn,checkOut,todayKey,role}) { const my=attendance.find(a=>a.date===todayKey&&(role==='employee'?a.employeeId==='EMP-001':a.employeeId==='OWNER')); return <><div className="page-heading"><div><div className="eyebrow">PEOPLE OPERATIONS</div><h1>Attendance & time</h1><p>Record your workday and review today's attendance entries.</p></div><div className="heading-actions"><button className="btn secondary" onClick={()=>window.print()}>⎙ Print report</button></div></div><div className="attendance-hero panel"><div className="attendance-intro"><span className="eyebrow">TODAY'S WORKDAY</span><h2>{new Date().toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</h2><p>Check in when you start, and check out when your workday ends.</p><div className="attendance-actions"><button className="btn primary" onClick={checkIn}>↘ Check in</button><button className="btn secondary" onClick={checkOut}>↗ Check out</button></div>{my&&<div className="check-status"><span className="live-dot"/> Checked in at <b>{my.checkIn}</b>{my.checkOut&&<> · Checked out at <b>{my.checkOut}</b></>}</div>}</div><div className="clock-art"><div className="clock-face"><span>9</span><span>12</span><span>3</span><span>6</span><i className="clock-hand hour"/><i className="clock-hand minute"/><i className="clock-pin"/></div></div></div><div className="stats-grid"><Stat label="Present today" value={attendance.filter(a=>a.status==='Present').length} change="Recorded check-ins" icon="✓" tone="green" foot="Not a verified location punch"/><Stat label="Team size" value={employees.length} change="Employee roster" icon="♙" tone="purple" foot="Configured employees"/><Stat label="Checked out" value={attendance.filter(a=>a.checkOut).length} change="End-of-day recorded" icon="◷" tone="blue" foot="Based on demo records"/><Stat label="Not checked out" value={attendance.filter(a=>!a.checkOut).length} change="May still be working" icon="!" tone="orange" foot="Confirm before payroll"/></div><div className="panel"><div className="panel-head"><div><h3>Today's attendance log</h3><p>{todayKey} · Browser-local demo data</p></div><span className="table-count">{attendance.length} records</span></div><div className="table-wrap"><table><thead><tr><th>TEAM MEMBER</th><th>DATE</th><th>CHECK-IN</th><th>CHECK-OUT</th><th>STATUS</th></tr></thead><tbody>{attendance.map((a,i)=><tr key={a.id}><td><div className="contact-cell"><div className={`tiny-avatar av-${i%4}`}>{a.name[0]}</div><b>{a.name}</b></div></td><td>{a.date}</td><td>{a.checkIn||'—'}</td><td>{a.checkOut||'—'}</td><td><Status value={a.status}/></td></tr>)}</tbody></table>{!attendance.length&&<Empty title="No attendance records today" desc="Use Check in to create a demo attendance record."/>}</div></div><div className="notice">Important: browser-local check-in is not secure attendance evidence. Production GPS, device policy, overtime rules and server timestamps require backend implementation.</div></>; }
function PayrollPage({payroll,employees,createPayroll,setPayroll,money}) { const [monthFilter,setMonthFilter]=useState('All'); const visible=payroll.filter(p=>monthFilter==='All'||p.month===monthFilter); const total=visible.reduce((s,p)=>s+Number(p.base||0)+Number(p.incentive||0)-Number(p.deductions||0),0); return <><div className="page-heading"><div><div className="eyebrow">PEOPLE OPERATIONS</div><h1>Payroll center</h1><p>Prepare monthly salary drafts, incentives and deductions for review.</p></div><div className="heading-actions"><button className="btn secondary" onClick={()=>window.print()}>⎙ Print</button><button className="btn primary" onClick={createPayroll}>＋ Generate monthly drafts</button></div></div><div className="stats-grid"><Stat label="Net payroll estimate" value={money(total)} change="Visible payroll entries" icon="₹" tone="purple" foot="Not a bank payment"/><Stat label="Drafts awaiting review" value={visible.filter(p=>p.status==='Draft').length} change="Not approved" icon="◷" tone="orange" foot="Review before paying"/><Stat label="Marked paid" value={visible.filter(p=>p.status==='Paid').length} change="Manual status only" icon="✓" tone="green" foot="No bank integration"/><Stat label="Employees" value={employees.length} change="Current roster" icon="♙" tone="blue" foot="Generated from base salaries"/></div><div className="notice">Payroll is an estimate-only prototype. PF/ESI/TDS, statutory compliance, payslip generation and payment proof must be implemented and reviewed before production use.</div><section className="panel"><div className="panel-head"><div><h3>Salary register</h3><p>Adjust incentive and deductions; then mark status as paid after external payment.</p></div><select className="filter-select" value={monthFilter} onChange={e=>setMonthFilter(e.target.value)}><option>All</option>{[...new Set(payroll.map(p=>p.month))].map(m=><option key={m}>{m}</option>)}</select></div><div className="table-wrap"><table><thead><tr><th>EMPLOYEE</th><th>MONTH</th><th>BASE SALARY</th><th>INCENTIVE</th><th>DEDUCTIONS</th><th>NET PAY</th><th>STATUS</th></tr></thead><tbody>{visible.map(p=><tr key={p.id}><td><b>{p.employee}</b><small className="cell-sub">{p.employeeId}</small></td><td>{p.month}</td><td>{money(p.base)}</td><td><input className="amount-input" type="number" value={p.incentive} onChange={e=>setPayroll(prev=>prev.map(x=>x.id===p.id?{...x,incentive:Number(e.target.value)}:x))}/></td><td><input className="amount-input" type="number" value={p.deductions} onChange={e=>setPayroll(prev=>prev.map(x=>x.id===p.id?{...x,deductions:Number(e.target.value)}:x))}/></td><td><b>{money(Number(p.base||0)+Number(p.incentive||0)-Number(p.deductions||0))}</b></td><td><select className="inline-select" value={p.status} onChange={e=>setPayroll(prev=>prev.map(x=>x.id===p.id?{...x,status:e.target.value}:x))}><option>Draft</option><option>Approved</option><option>Paid</option></select></td></tr>)}</tbody></table>{!visible.length&&<Empty title="No payroll drafts yet" desc="Generate monthly drafts from the current employee base salaries."/>}</div></section></>; }
function ReportsPage({leads,employees,properties,money}) { const stages=['New','Qualified','Hot','Site Visit','Negotiation','Won','Lost']; const max=Math.max(...stages.map(s=>leads.filter(l=>l.status===s).length),1); return <><PageTitle eyebrow="BUSINESS INTELLIGENCE" title="Reports & insights" subtitle="Understand pipeline health and your team's workload at a glance."/><div className="stats-grid"><Stat label="Open pipeline value" value={money(leads.filter(l=>!['Won','Lost'].includes(l.status)).reduce((s,l)=>s+Number(l.budget||0),0))} change="Budget sum, not forecast" icon="₹" tone="purple" foot="Review probability weighting"/><Stat label="Conversion rate" value={`${leads.length?Math.round(leads.filter(l=>l.status==='Won').length/leads.length*100):0}%`} change="Won / total leads" icon="↗" tone="green" foot="Demo data calculation"/><Stat label="Team size" value={employees.length} change="Current roster" icon="♙" tone="blue" foot="No productivity scoring yet"/><Stat label="Inventory value" value={money(properties.reduce((s,p)=>s+Number(p.price||0),0))} change="Sum of listing prices" icon="⌂" tone="orange" foot="Not company-owned asset value"/></div><div className="dashboard-grid"><div className="panel"><div className="panel-head"><div><h3>Pipeline distribution</h3><p>Lead count by stage</p></div></div><div className="pipeline-bars report-bars">{stages.map((s,i)=>{const count=leads.filter(l=>l.status===s).length;return <div className="pipeline-row" key={s}><span>{s}</span><div className="bar-track"><div className="bar-fill" style={{width:`${count/max*100}%`}}/></div><b>{count}</b></div>})}</div></div><div className="panel"><div className="panel-head"><div><h3>Suggested actions</h3><p>Improve the quality of reporting</p></div></div><div className="insight-list"><div><span className="insight-badge purple">01</span><p><b>Capture lost reasons</b><small>Understand why opportunities are not converting.</small></p></div><div><span className="insight-badge orange">02</span><p><b>Track response time</b><small>Use timestamped activities from the backend.</small></p></div><div><span className="insight-badge green">03</span><p><b>Verify property availability</b><small>Keep last-confirmed date and source for every listing.</small></p></div></div></div></div></>; }
function SettingsPage({settings,setSettings,company,setToast}) { return <><PageTitle eyebrow="WORKSPACE CONFIGURATION" title="Settings & branding" subtitle="Configure the look and defaults for this demo workspace."/><div className="settings-layout"><section className="panel settings-form"><div className="panel-head"><div><h3>Brand identity</h3><p>White-label settings preview</p></div></div><label className="settings-label">Company / brand name<input value={settings.companyName} onChange={e=>setSettings({...settings,companyName:e.target.value})}/></label><label className="settings-label">Brand accent color<div className="color-setting"><input type="color" value={settings.brandColor} onChange={e=>setSettings({...settings,brandColor:e.target.value})}/><code>{settings.brandColor}</code></div></label><label className="settings-label">Currency<select value={settings.currency} onChange={e=>setSettings({...settings,currency:e.target.value})}><option value="INR">INR — Indian Rupee</option><option value="USD">USD — US Dollar</option></select></label><label className="settings-label">Timezone<select value={settings.timezone} onChange={e=>setSettings({...settings,timezone:e.target.value})}><option value="Asia/Kolkata">Asia/Kolkata</option><option value="UTC">UTC</option></select></label><button className="btn primary" onClick={()=>setToast('Brand settings saved in this browser')}>Save workspace settings</button><div className="notice">In this prototype, branding is saved in this browser. Production white-label settings must be stored per tenant in the secured backend.</div></section><section className="panel brand-preview"><div className="panel-head"><div><h3>Live brand preview</h3><p>How the company appears in navigation</p></div></div><div className="preview-window"><div className="preview-top"><div className="preview-mark" style={{background:settings.brandColor}}>E+</div><div><b>{settings.companyName||company?.name}</b><small>CRM WORKSPACE</small></div></div><div className="preview-hero" style={{background:`linear-gradient(135deg, ${settings.brandColor}, #171b37)`}}><span>WORKSPACE OVERVIEW</span><h3>Your business,<br/>in one flow.</h3><p>Leads · Team · Property · Growth</p></div><div className="preview-kpis"><div><small>Leads</small><b>128</b></div><div><small>Visits</small><b>16</b></div><div><small>Bookings</small><b>08</b></div></div></div></section></div><section className="panel security-panel"><div className="panel-head"><div><h3>Production readiness checklist</h3><p>Complete these before onboarding paying customers.</p></div><span className="status-pill warning">Not production-ready</span></div>{['Real authentication with password reset and MFA option','Tenant isolation enforced by backend policies','Server-side role and feature permissions','Database backups and tested restore procedure','Subscription billing, plan limits and cancellation handling','Audit log for sensitive changes and exports','Privacy policy, terms, data retention and deletion workflow'].map((x,i)=><div className="checklist-row" key={x}><span className="check-number">{String(i+1).padStart(2,'0')}</span><span>{x}</span><span className="status-pill neutral">Pending</span></div>)}</section></>; }
function PageTitle({eyebrow,title,subtitle,actions}) { return <div className="page-heading"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{subtitle}</p></div>{actions&&<div className="heading-actions">{actions}</div>}</div>; }
function Field({label,required,wide,children}) { return <label className={`field ${wide?'wide':''}`}><span>{label}{required&&' *'}</span>{children}</label>; }
function Modal({title,onClose,children}) { return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><section className="modal"><div className="modal-head"><h2>{title}</h2><button onClick={onClose} aria-label="Close">×</button></div>{children}</section></div>; }
function Status({value}) { const v=String(value||'Unknown'); const key=v.toLowerCase().replace(/[^a-z]+/g,'-'); return <span className={`status-pill status-${key}`}>{v}</span>; }
function Empty({title,desc}) { return <div className="empty-state"><div>✦</div><h3>{title}</h3><p>{desc}</p></div>; }
